import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.level.block.Block;
import rbasamoyai.createbigcannons.compat.common_jei.HardcodedBlockRecipe;
import rbasamoyai.createbigcannons.crafting.incomplete.IncompleteWithItemsCannonBlock;
import rbasamoyai.createbigcannons.utils.CBCRegistryUtils;

public class IncompleteCannonBlockRecipe
extends HardcodedBlockRecipe {
    private final List<ItemStack> ingredients = new ArrayList<ItemStack>();

    public IncompleteCannonBlockRecipe(ResourceLocation id, Block result, Block start) {
        super(id, result);
        this.ingredients.add(new ItemStack((ItemLike)start));
        if (start instanceof IncompleteWithItemsCannonBlock) {
            IncompleteWithItemsCannonBlock incomplete = (IncompleteWithItemsCannonBlock)start;
            incomplete.requiredItems().stream().map(ItemStack::new).forEach(this.ingredients::add);
        }
    }

    @Override
    public List<ItemStack> ingredients() {
        return this.ingredients;
    }

    public static Collection<IncompleteCannonBlockRecipe> makeAllIncompleteRecipes() {
        return CBCRegistryUtils.streamAllBlocks().filter(IncompleteWithItemsCannonBlock.class::isInstance).map(b -> new IncompleteCannonBlockRecipe(null, ((IncompleteWithItemsCannonBlock)b).getCompleteBlockState(b.m_49966_()).m_60734_(), (Block)b)).toList();
    }
}

